import React, { useState } from 'react';
import {
  Stack,
  Typography,
  TextField,
  Button,
  Checkbox,
  FormControlLabel,
  FormControl,
  FormLabel,
} from '@mui/material';
import Autocomplete from '@mui/material/Autocomplete';
import FormGroup from '@mui/material/FormGroup';
import { styled } from '@mui/material/styles';
import { axios } from '../../utils/axios';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import useResponsive from '../../hooks/useResponsive';
import { useMyContext } from '../provider';

const InputContainer = styled('div')({
  display: 'flex',
  alignItems: 'center',
  gap: '8px',
  marginBottom: '16px',
});

const SendNotification = () => {
  const [showUsers, setShowUsers] = useState(false);
  const [showProviders, setShowProviders] = useState(false);
  const [userOptions, setUserOptions] = useState([]);
  const [userId, setUserId] = useState([]);
  const [selectedOptions, setSelectedOptions] = useState([]);
  const [usertype, setUserType] = useState('');
  const [providertype, Setprovidertype] = useState('');
  const [messages, setMessages] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const { i18 } = useMyContext()

  const options = showUsers ? userOptions : [];

  const isDisableButton = !messages || !usertype;

  const isMobile = useResponsive("down", "sm")

  const handleSendNotification = async (event) => {
    event.preventDefault();
    const forWhom = `[${selectedOptions.map((item) => item._id).toString()}]`;
    try {
      const data = {
        message: messages,
        userType: usertype.toUpperCase() || providertype.toUpperCase(),
        forWhom,
      };
      const res = await axios.post('/module/notifications/send', data);

      if (res.status === 200) {
        GenerateToastConfig('Notification sent successfully', 'success');
        setMessages('');
        setSearchTerm('');
        setShowUsers('')
        setSelectedOptions([])

      } else {
        GenerateToastConfig('Failed to send notification');
      }
    } catch (err) {
      GenerateToastConfig('Error sending notification: ', err.message);
    }
  };

  const handleUserChange = async (event) => {
    setShowUsers(event.target.checked);
    setUserType(event.target.checked ? 'user' : '');
    setShowProviders(false);
    if (event.target.checked) {
      try {
        const response = await axios.get('module/auth/users/list');
        setUserOptions(response.data.data.users);
        setUserId(response.data.data.users.map((user) => user._id));
      } catch (error) {
        console.error('Error fetching user data:', error);
      }
    } else {
      setUserOptions([]);
    }
  };

  return (
    <div>
      <Stack direction="row" alignItems="center" justifyContent="space-between" mb={5}>
        <Typography variant="h4" gutterBottom>
          {i18?.ADMIN_NOTIFICATION?.SEND_NOTIFICATIONS || "Send Notifications"}
        </Typography>
      </Stack>
      <form onSubmit={handleSendNotification} style={{ width: isMobile ? "100%" : '50%', margin: '0 auto' }}>
        <Stack direction="column" spacing={2}>
          <TextField
            id="message"
            label="Message"
            variant="outlined"
            multiline
            rows={4}
            value={messages}
            onChange={(e) => setMessages(e.target.value)}
          />
          <FormControl component="fieldset">
            <FormLabel component="legend">{i18?.ADMIN_NOTIFICATION?.MESSAGE_TO || "Message To"}: </FormLabel>
            <FormGroup>
              <FormControlLabel
                control={<Checkbox checked={showUsers} onChange={handleUserChange} disabled={showProviders} />}
                label={i18?.ADMIN_NOTIFICATION?.USER || "User"}
              />
            </FormGroup>
          </FormControl>

          {(showUsers || showProviders) && (
            <Stack spacing={2}>
              <InputContainer>
                <Autocomplete
                  multiple
                  id="tags-filled"
                  options={options}
                  defaultValue={[]}
                  getOptionLabel={(option) => option.firstname}
                  onChange={(_, newValue) => {
                    setSelectedOptions(newValue);
                  }}
                  value={selectedOptions}
                  renderInput={(params) => (
                    <TextField
                      {...params}
                      variant="outlined"
                      label="Name"
                      placeholder="Type and select names"
                      style={{ width: '480px' }}
                      onChange={(e) => setSearchTerm(e.target.value)}
                    />
                  )}
                />
              </InputContainer>
            </Stack>
          )}
          <Button type="submit" variant="contained" disabled={isDisableButton} color="primary">
            {i18?.ADMIN_NOTIFICATION?.SEND || "Send"}
          </Button>
          <br />
        </Stack>
      </form>
    </div>
  );
};

export default SendNotification; 
